/* ================= DATA: SCENARIOS ============================================
   Node fields: id, ph (phase), kc (kill chain stage), at (clock jump, hours from start),
   enter (fx applied on arrival), if/unless (show only if flag set / skip if set),
   hours (override base time), art (evidence block), att (technique ids, first one is quizzed),
   obs (behaviour described in the quiz), disc (workshop prompt), opts.
   Option fields: q (0 poor .. 3 best), t (text), r (result), f (fail result), w (why),
   u (controls that change the odds), p (base odds), fx (extra effects), set (flag), esc (force escalation), next.
   ========================================================================== */

const SCEN = [];

