          art: "17:12 SearchQuery     user={fdmail}  query='password'\n17:14 SearchQuery     user={fdmail}  query='vcenter'\n17:15 FileAccessed    IT-Handover-2023.xlsx  site=/sites/IT-Archive\n17:41 FileDownloaded  IT-Handover-2023.xlsx",
